function montarCartao(idDestino) { document.getElementById(idDestino).innerHTML = CARTAO_HTML; ajustarEscalaCartoes(); }

// Escala os cartoes (500x316) para caber em qualquer tela: celular, tablet, desktop, retrato ou paisagem.
function definirEscalaCartoes(s) {
  document.querySelectorAll('#printArea .cardwrap').forEach(w => {
    w.style.width = (500 * s) + 'px';
    w.style.height = (316 * s) + 'px';
    w.firstElementChild.style.transform = s === 1 ? 'none' : 'scale(' + s + ')';
  });
}
function ajustarEscalaCartoes() {
  const area = document.getElementById('printArea');
  if (!area) return;
  const pai = area.parentElement;
  let largura = pai.getBoundingClientRect().width;
  if (!largura) largura = window.innerWidth - 20;
  largura = Math.min(largura, window.innerWidth) - 4;
  const sLado = (largura - 28) / 1000;                // escala para frente e verso lado a lado
  const paisagem = window.innerWidth > window.innerHeight;
  let s;
  if (sLado >= 1) s = 1;                              // tela larga: lado a lado, tamanho real
  else if (paisagem && sLado >= 0.7) s = sLado;       // celular/tablet deitado: lado a lado, tudo visivel de uma vez
  else s = Math.max(0.5, Math.min(1.5, largura / 500));   // retrato: um embaixo do outro, largura total
  definirEscalaCartoes(s);
}
window.addEventListener('resize', ajustarEscalaCartoes);
window.addEventListener('orientationchange', () => setTimeout(ajustarEscalaCartoes, 200));

// Reduz a letra ate o texto caber na caixa (nada fica cortado, nem na tela nem no PDF).
function ajustarTextoCartao(el, larguraMax) {
  if (!el) return;
  el.style.fontSize = '';
  let tam = parseFloat(getComputedStyle(el).fontSize);
  const lim = larguraMax || el.clientWidth;
  while (el.scrollWidth > lim + 0.5 && tam > 6) { tam -= 0.5; el.style.fontSize = tam + 'px'; }
}
function ajustarTodosTextos() {
  ['cardNome', 'cardGrad', 'cardEstilo', 'cardEntidade', 'cardCNKB'].forEach(id => ajustarTextoCartao(document.getElementById(id)));
  const cg = document.getElementById('cardCargo');
  if (cg) { cg.style.fontSize = ''; let t = parseFloat(getComputedStyle(cg).fontSize); while (cg.parentElement.scrollWidth > 440 && t > 6) { t -= 0.5; cg.style.fontSize = t + 'px'; } }
}
function regTxt(r) { return (r === null || r === undefined) ? '----' : String(r).padStart(4, '0'); }
function linhaParaAtleta(l) { return { r: l.registro, n: l.nome, g: l.graduacao, e: l.estilo, d: l.associacao, dn: l.associacao_nome, s: l.anuidade, cnkb: l.cnkb, cargo: l.cargo, tok: l.qr_token }; }
function atletaAtivo(l) { return /202[67]/.test(String(l.anuidade || l.s || '')); }
const NOMES_ASSOCIACOES = {
      "AFC": "Projeto Forma-se um Campeão (AFC)",
      "ASKAF": "Associação de Karate Fluminense (ASKAF)",
      "GOJUKAN": "Academia Goju Kan (GOJUKAN)",
      "GKDK": "Goju Ryu Karate-do Danketsu Kyokai (GKDK)",
      "FTDK": "Falcão's Team Dojo Karate (FTDK)",
      "LIONS": "Associação Lions Karate Team (LIONS)",
      "MFT": "Escola Menkyo Kai Fight Team (MFT)",
      "PETRVM": "Associação Pé na Trilha das Agulhas Negras (PETRVM)",
      "OSKW": "Associação Old School Karate-do Wado-Ryu (OSKW)",
      "AVKS": "Associação Village de Karate Shotokan (AVKS)",
      "PECAMPEOES": "Projeto Escola de Campeões (PECAMPEOES)",
      "GOSHIKAN": "Academia Goshi Kan (GOSHIKAN)",
      "KGKVLC": "Associação Karate-do Gosei Kan (KGKVLC)",
      "MINAMIHARA": "Associação Minamihara de Karate Tradicional (MINAMIHARA)",
      "CHKS": "Dojo Chimu Honorato Karate Shotokan (CHKS)",
      "AKATSUKI": "Associação Dojo Akatzuki de Karate (AKATSUKI)",
      "PSKP": "Projeto Social Karate Pantaneiro (PSKP)"
    };

    // Logomarcas oficiais embutidas, por sigla da associação
    const LOGOS_ASSOCIACOES = {"AFC": "data:image/png;base64,", "ASKAF": "data:image/png;base64,", "GOJUKAN": "data:image/png;base64,", "GKDK": "data:image/png;base64,", "FTDK": "data:image/png;base64,", "LIONS": "data:image/png;base64,", "MFT": "data:image/png;base64,", "PETRVM": "data:image/png;base64,", "OSKW": "data:image/png;base64,", "AVKS": "data:image/png;base64,", "PECAMPEOES": "data:image/png;base64,", "GOSHIKAN": "data:image/png;base64,", "KGKVLC": "data:image/png;base64,", "MINAMIHARA": "data:image/png;base64,", "CHKS": "data:image/png;base64,", "AKATSUKI": "data:image/png;base64,", "PSKP": "data:image/png;base64,"};

    // Gera automaticamente um brasão vetorizado específico e elegante para cada associação
    function gerarLogoAssociacaoSVG(sigla) {
      const cores = {
        "AFC": { borda: "#BE1622", fundo: "#FEF2F2", texto: "#991B1B", detalhe: "#DC2626" },
        "ASKAF": { borda: "#009FE3", fundo: "#F0F9FF", texto: "#0369A1", detalhe: "#0284C7" },
        "GOJUKAN": { borda: "#009640", fundo: "#F0FDF4", texto: "#166534", detalhe: "#15803D" },
        "PETRVM": { borda: "#D4AF37", fundo: "#FFFBEB", texto: "#78350F", detalhe: "#B45309" },
        "MFT": { borda: "#111827", fundo: "#F9FAFB", texto: "#111827", detalhe: "#374151" },
        "LIONS": { borda: "#EA580C", fundo: "#FFF7ED", texto: "#9A3412", detalhe: "#C2410C" },
        "GKDK": { borda: "#4F46E5", fundo: "#EEF2FF", texto: "#3730A3", detalhe: "#4338CA" },
        "FTDK": { borda: "#DC2626", fundo: "#FEF2F2", texto: "#991B1B", detalhe: "#B91C1C" },
        "OSKW": { borda: "#0D9488", fundo: "#F0FDFA", texto: "#115E59", detalhe: "#0F766E" },
        "AVKS": { borda: "#2563EB", fundo: "#EFF6FF", texto: "#1E40AF", detalhe: "#1D4ED8" },
        "PSKP": { borda: "#059669", fundo: "#ECFDF5", texto: "#065F46", detalhe: "#047857" },
        "AKATSUKI": { borda: "#991B1B", fundo: "#FEF2F2", texto: "#7F1D1D", detalhe: "#DC2626" }
      };

      const c = cores[sigla] || { borda: "#009FE3", fundo: "#F8FAFC", texto: "#0F172A", detalhe: "#334155" };

      return `
        <svg viewBox="0 0 100 100" class="w-full h-full" xmlns="http://www.w3.org/2000/svg">
          <circle cx="50" cy="50" r="46" fill="${c.fundo}" stroke="${c.borda}" stroke-width="4"/>
          <circle cx="50" cy="50" r="38" fill="none" stroke="${c.detalhe}" stroke-width="1.5" stroke-dasharray="3,2"/>
          <text x="50" y="55" font-family="'Cinzel', Impact, sans-serif" font-size="21" font-weight="900" fill="${c.texto}" text-anchor="middle" letter-spacing="0.5">${sigla}</text>
          <path d="M 30 70 Q 50 78 70 70" fill="none" stroke="${c.borda}" stroke-width="2"/>
        </svg>
      `;
    }

    
function fundoCartao(verde) {
  const L = verde ? '150,240,180' : '120,190,255', D = verde ? '0,45,20' : '0,15,90', M = verde ? '90,220,140' : '70,140,255';
  return '<svg class="bg" viewBox="0 0 500 316" preserveAspectRatio="none" xmlns="http://www.w3.org/2000/svg">' +
    '<polygon points="0,316 0,150 190,316" fill="rgba(255,255,255,0.08)"/>' +
    '<polygon points="40,0 210,0 0,190 0,60" fill="rgba(' + L + ',0.14)"/>' +
    '<polygon points="500,0 500,170 330,0" fill="rgba(' + D + ',0.25)"/>' +
    '<polygon points="500,316 500,120 250,316" fill="rgba(' + M + ',0.18)"/>' +
    '<polygon points="0,0 140,0 0,95" fill="rgba(' + D + ',0.25)"/></svg>';
}

function renderizarCartao(atleta) {
  window.atletaAtual = atleta;
  const $ = id => document.getElementById(id);
  const grad = String(atleta.g || '').toUpperCase();
  const isPreta = grad.includes('PRETA') || grad.includes('DAN');
  const verde = !isPreta;           // faixa preta = azul; 10o a 1o kyu = verde

  ['cardFront', 'cardBack'].forEach(id => {
    $(id).classList.toggle('verde', verde);
    $(id).querySelector('.fundo').innerHTML = fundoCartao(verde);
  });

  $('cardReg').innerText = 'REG: Nº ' + regTxt(atleta.r);
  $('cardNome').innerText = atleta.n;
  $('cardGrad').innerText = atleta.g || '';
  $('cardEstilo').innerText = String(atleta.e || '').replace(/^GOJU\s*RYU\s+SEIGOKAN(\s+II)?$/i, 'GOJU RYU SEIGOKAN');
  $('cardEntidade').innerText = atleta.d;           // so a sigla da associacao
  $('authHash').innerText = 'HASH: FIK-' + regTxt(atleta.r) + '-AUT';
  $('cardTitulo').innerText = isPreta ? 'CARTEIRA DO PROFESSOR' : 'CARTEIRA DO ESTUDANTE';

  const box = $('assocLogoBox');
  box.innerHTML = LOGOS_ASSOCIACOES[atleta.d]
    ? '<img src="' + LOGOS_ASSOCIACOES[atleta.d] + '" alt="' + atleta.d + '">'
    : gerarLogoAssociacaoSVG(atleta.d);

  const cargo = (atleta.cargo || '').trim();
  const tarja = $('cardTarja');
  if (cargo) {
    $('cardCargo').innerText = cargo;
    $('boxCargoDiretoria').style.display = 'inline-block';
    const pres = cargo.includes('PRESIDENTE') && !cargo.includes('VICE');
    tarja.innerText = pres ? 'PRESIDENTE' : 'DIRETORIA';
    tarja.className = 'tarja ouro';
  } else {
    $('boxCargoDiretoria').style.display = 'none';
    tarja.innerText = isPreta ? 'PROFESSOR' : 'ESTUDANTE';
    tarja.className = 'tarja ' + (isPreta ? 'prof' : 'est');
  }

  $('cardCNKB').innerText = atleta.cnkb || (isPreta ? 'FILIADO CNKB' : 'NÃO APLICÁVEL');

  const qr = $('qrcode');
  qr.innerHTML = '';
  const urlValidacao = new URL('validar.html', window.location.href).href + '?t=' + atleta.tok;
  new QRCode(qr, { text: urlValidacao, width: 70, height: 70, colorDark: '#000000', colorLight: '#ffffff', correctLevel: QRCode.CorrectLevel.M });
  ajustarEscalaCartoes();
  ajustarTodosTextos();
}

async function gerarPDFCartoes(lista, nomeArquivo, aoProgredir) {
  // lista: atletas no formato do cartao; um por pagina A4 paisagem, frente e verso lado a lado
  const pdf = new window.jspdf.jsPDF({ unit: 'mm', format: 'a4', orientation: 'landscape' });
  if (document.fonts && document.fonts.ready) await document.fonts.ready;
  definirEscalaCartoes(1);
  for (let i = 0; i < lista.length; i++) {
    if (aoProgredir) aoProgredir(i + 1, lista.length);
    renderizarCartao(lista[i]);
    await new Promise(r => setTimeout(r, 200));
    const frente = await html2canvas(document.getElementById('cardFront'), { scale: 3, useCORS: true, backgroundColor: '#ffffff', windowWidth: 1300 });
    const verso = await html2canvas(document.getElementById('cardBack'), { scale: 3, useCORS: true, backgroundColor: '#ffffff', windowWidth: 1300 });
    if (i > 0) pdf.addPage('a4', 'landscape');
    pdf.addImage(frente.toDataURL('image/jpeg', 0.95), 'JPEG', 13, 50, 130, 82.1);
    pdf.addImage(verso.toDataURL('image/jpeg', 0.95), 'JPEG', 154, 50, 130, 82.1);
  }
  pdf.save(nomeArquivo);
  ajustarEscalaCartoes();
}
